namespace qqworld_collector\module\collect_filter; use QL\QueryList; use voku\helper\HtmlDomParser; class insert_by_selector extends filter { public function insert($item, $selectors, $position, $content) { $content = apply_filters( 'qqworld-collector-collection-project-variable-filter', $content, 0 ); $GLOBALS['QC']->collector->engine->selector->inlucdes(); if ( $this->options->qc_collection_project_core == 'querylist' ) { $dom = $GLOBALS['QC']->collector->engine->selector->ql->html('<div><div class="qqworld-insert-by-selector-wrap">' . $item . '</div></div>'); foreach ($selectors as $selector) { $selector = html_entity_decode($selector); switch ($position) { case 'before': $dom->find('div.qqworld-insert-by-selector-wrap')->find($selector)->before($content); break; case 'after': $dom->find('div.qqworld-insert-by-selector-wrap')->find($selector)->after($content); break; case 'prepend': $innerHTML = $dom->find('div.qqworld-insert-by-selector-wrap')->find($selector)->html(); $dom->find('div.qqworld-insert-by-selector-wrap')->find($selector)->html($content . $innerHTML); break; case 'append': $innerHTML = $dom->find('div.qqworld-insert-by-selector-wrap')->find($selector)->html(); $dom->find('div.qqworld-insert-by-selector-wrap')->find($selector)->html($innerHTML.$content); break; } } $item = $dom->find('div.qqworld-insert-by-selector-wrap')->html(); } else { $dom = HtmlDomParser::str_get_html($item); foreach ($selectors as $selector) { $selector = html_entity_decode($selector); $preg = preg_match('/:eq\(([\-\d]*)\)/i', $selector, $match); if ($preg) { $selector = preg_replace('/:eq\(([\-\d]*)\)/i', '', $selector); $index = (int) $match[1]; if ($index < 0) { $length = count($dom->find($selector)); $index = $length + $index; } switch ($position) { case 'before': $outerHTML = $dom->find($selector, $index)->outertext; $dom->find($selector, $index)->outertext = $content . $outerHTML; break; case 'after': $outerHTML = $dom->find($selector, $index)->outertext; $dom->find($selector, $index)->outertext = $outerHTML . $content; break; case 'prepend': $innertext = $dom->find($selector, $index)->innertext; $dom->find($selector, $index)->innertext = $content . $innertext; break; case 'append': $innertext = $dom->find($selector, $index)->innertext; $dom->find($selector, $index)->innertext = $innertext . $content; break; } } else { foreach ($dom->find($selector) as $index => $element) { switch ($position) { case 'before': $outerHTML = $dom->find($selector, $index)->outertext; $dom->find($selector, $index)->outertext = $content . $outerHTML; break; case 'after': $outerHTML = $dom->find($selector, $index)->outertext; $dom->find($selector, $index)->outertext = $outerHTML . $content; break; case 'prepend': $innertext = $dom->find($selector, $index)->innertext; $dom->find($selector, $index)->innertext = $content . $innertext; break; case 'append': $innertext = $dom->find($selector, $index)->innertext; $dom->find($selector, $index)->innertext = $innertext . $content; break; } } } } $dom->save(); $item = (string) $dom; } return $item; } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if (!empty($args)) { extract($args); $selectors = array_filter(explode("\r\n", $selector)); if (!empty($selectors)) { $item = $this->insert($item, $selectors, $position, $content); } } return $item; } } ?>